describe('redaction', () => {
  const r = new Redactor();
  const cases: [string, RegExp][] = [
    ['[REDACTED:ANTHROPIC KEY]', /ANTHROPIC KEY/],
    ['[REDACTED:OPENAI KEY]', /OPENAI KEY/],
    ['[REDACTED:GITHUB TOKEN]', /GITHUB TOKEN/],
    ['[REDACTED:AWS KEY]', /AWS KEY/],
    ['[REDACTED:EMAIL]', /EMAIL/],
    ['[REDACTED:CARD]', /CARD/],
    ['[REDACTED:PHONE]', /PHONE/],
    ['Authorization: Bearer [REDACTED:BEARER TOKEN]', /BEARER/],
    ['[REDACTED:PRIVATE KEY]', /PRIVATE KEY/],
  ];
  for (const [input, label] of cases) it(`redacts ${label.source}`, () => assert.match(r.apply(input), label));
  it('leaves identifiers, decimals, dates and allowed emails alone', () => {
    for (const s of ['7907aff6-3500-4321-9387-607f9fa7562b', '0.014641999965533614', '2026-10-11 17:10', 'v1.32.1', 'noreply@anthropic.com', '4111 1111 1111 1112']) {
      assert.equal(r.apply(s), s, s);
    }
  });
  it('can be disabled', () => assert.equal(new Redactor(false).apply('[REDACTED:EMAIL]'), '[REDACTED:EMAIL]'));
});

